<?php
// Included only by the authenticated Meu saldo route; never accepts another player ID.
declare(strict_types=1);
if(!defined('PROJECT_PATH')){http_response_code(404);exit;}
requireProjectAuth();if(!financeTeamEnabled()){http_response_code(404);exit;}financeEnsureEntryMetaSchema($pdo);
$user=projectUser();if(!$user||$user['status']!=='active'){http_response_code(403);exit('Acesso negado.');}
$s=$pdo->prepare('SELECT id,name FROM players WHERE user_id=?');$s->execute([(int)$user['id']]);$matches=$s->fetchAll(PDO::FETCH_ASSOC);
if(count($matches)!==1){http_response_code(403);exit('Seu acesso precisa estar vinculado a um unico jogador.');}
$player=$matches[0];$received=financeTeamChargeReceivedSql();$s=$pdo->prepare("SELECT c.*,$received AS received_amount FROM finance_team_charges c WHERE beneficiary_player_id=? ORDER BY id DESC LIMIT 100");$s->execute([$player['id']]);$charges=$s->fetchAll(PDO::FETCH_ASSOC);
$s=$pdo->prepare('SELECT kind,amount,status,movement_date FROM finance_team_credit_movements WHERE player_id=? ORDER BY id DESC LIMIT 100');$s->execute([$player['id']]);$credits=$s->fetchAll(PDO::FETCH_ASSOC);$title='Meu financeiro';ob_start();
?>
<?php $requests=$pdo->prepare('SELECT amount,status,created_at FROM finance_wallet_requests WHERE user_id=? ORDER BY id DESC LIMIT 10');$requests->execute([(int)$user['id']]); ?>
<div class="c-page"><div class="c-page-header"><h1 class="c-page-title">Meu financeiro</h1></div><div class="c-page-content"><div class="c-card"><h3><?= htmlspecialchars($player['name']) ?></h3><p>Credito disponivel: <strong><?= financeMoney(financeTeamCreditBalance($pdo,(int)$player['id'])/100) ?></strong></p><p>A receber: <?= financeMoney((float)financeTeamOutstanding($pdo,(int)$player['id'])) ?></p><?php $pix=financeCorePixSettings();if($pix['upgrade_pix_key']!==''): ?><p>Pix do time: <?= htmlspecialchars($pix['upgrade_pix_key']) ?> · <?= htmlspecialchars($pix['upgrade_pix_holder']) ?></p><?php endif; ?></div><?php if($pix['upgrade_pix_key']!==''): ?><details class="c-card"><summary>Enviar comprovante de credito</summary><form action="<?= PROJECT_URL ?>/admin/financeiro/wallet_request_store.php" method="post" enctype="multipart/form-data"><?= csrf_field() ?><label>Valor enviado</label><input type="number" name="amount" class="c-input" required min="0.01" step="0.01"><label>Comprovante</label><input type="file" name="receipt" class="c-input" required accept=".jpg,.jpeg,.png,.webp,.pdf"><button class="c-btn-secondary">Enviar para conferencia</button></form><?php foreach($requests->fetchAll(PDO::FETCH_ASSOC) as $request): ?><p><?= htmlspecialchars($request['created_at']) ?> · <?= financeMoney((float)$request['amount']) ?> · <?= htmlspecialchars(financeWalletStatusLabel($request['status'])) ?></p><?php endforeach; ?></details><?php endif; ?><div class="c-card"><h3>Minhas cobrancas</h3><?php foreach($charges as $charge): ?><p><?= htmlspecialchars($charge['title'].' · '.$charge['due_date']) ?> · Total <?= financeMoney((float)$charge['total_amount']) ?> · Quitado <?= financeMoney((float)$charge['received_amount']) ?><?= $charge['status']==='canceled'?' · Cancelada':'' ?></p><?php endforeach; ?></div><div class="c-card"><h3>Meus creditos</h3><?php foreach($credits as $credit): ?><p><?= htmlspecialchars($credit['movement_date']) ?> · <?= ['deposit'=>'Recebido','use'=>'Utilizado','refund'=>'Devolvido'][$credit['kind']] ?> · <?= financeMoney((float)$credit['amount']) ?><?= $credit['status']==='canceled'?' · Cancelado':'' ?></p><?php endforeach; ?></div></div></div>
